func reverseLeftWords(s string, n int) string {
	a := []byte(s)
	if len(a) == 0 {
		return s
	}
	n %= len(a)
	rev := func(i, j int) {
		for i < j {
			a[i], a[j] = a[j], a[i]
			i++
			j--
		}
	}
	rev(0, n-1)
	rev(n, len(a)-1)
	rev(0, len(a)-1)
	return string(a)
}

