func evalRPN(tokens []string) int {
	st := []int{}
	for _, tk := range tokens {
		if tk == "+" || tk == "-" || tk == "*" || tk == "/" {
			b, a := st[len(st)-1], st[len(st)-2]
			st = st[:len(st)-2]
			switch tk {
			case "+":
				st = append(st, a+b)
			case "-":
				st = append(st, a-b)
			case "*":
				st = append(st, a*b)
			default:
				st = append(st, a/b)
			}
		} else {
			v, _ := strconv.Atoi(tk)
			st = append(st, v)
		}
	}
	return st[0]
}

